/* 本地渲染自检（不参与角色卡导出）。
 *
 * 页面按网址参数直接落在某一页（`?页=商店&类=服装店`），把这一页的可见文字抄进报告区。
 * 为什么用参数而不是点按钮：无头浏览器里合成点击唤不起 Vue 的处理函数，
 * 所以本地看页面靠参数开局，`src/知夏/界面/面板/App.vue` 与 `ShopTab.vue` 里各有一处读参数的小口子。
 *
 * 它替代不了实机。变量写回、游戏结算、与正文的联动都要在酒馆里验。
 */
import { createApp } from 'vue';
import App from './App.vue';
$(() => {
    const app = createApp(App).use(createPinia());
    app.mount('#app');
    $(window).on('pagehide', () => app.unmount());
});
const 框 = document.getElementById('自测结果');
function 报(话) {
    框.style.display = 'block';
    框.textContent += 话 + '\n';
}
let 走过 = false;
window.setTimeout(() => {
    框.style.cssText =
        'position:fixed;left:0;right:0;bottom:0;max-height:48%;overflow:auto;padding:10px 12px;background:#1f2a24;color:#cfe8d4;font:12px/1.5 monospace;white-space:pre-wrap;z-index:9999';
    尝试(0);
}, 400);
function 尝试(第几次) {
    if (走过)
        return;
    if (!document.querySelector('.zx-panel')) {
        // 面板要等 CDN 上的 Vue 与 pinia 到位才挂得上，慢的时候要十几秒。
        if (第几次 >= 30) {
            报('等了 12 秒面板还是没渲染出来。');
            const 报错框 = document.getElementById('预览报错');
            报('页面报错：' + (报错框 ? (报错框.textContent ?? '').replace(/\s+/g, ' ').slice(0, 600) : '没有报错框。'));
            return;
        }
        window.setTimeout(() => 尝试(第几次 + 1), 400);
        return;
    }
    走过 = true;
    抄这一页();
}
function 抄这一页() {
    const 参数 = new URLSearchParams(window.location.search);
    const 页 = 参数.get('页') ?? '打工';
    const 类 = 参数.get('类');
    报('打开的是：' + 页 + (类 ? ' · ' + 类 : ''));
    const 短文 = (document.querySelector('.zx-body')?.textContent ?? '').replace(/\s+/g, ' ').trim();
    报(短文.slice(0, 1400));
    if (页 === '商店') {
        const 卡数 = document.querySelectorAll('.zx-goods .zx-good').length;
        const 空 = document.querySelector('.zx-空')?.textContent?.trim();
        报('');
        报('这一类的货卡数量：' + 卡数 + (空 ? '，页面显示：' + 空 : ''));
        报('二级导航：' + [...document.querySelectorAll('.zx-shop-nav button')].map(b => b.textContent?.trim()).join(' / '));
    }
    if (页 === '妹妹' || 页 === '日历') {
        const 段数 = document.querySelectorAll('.zx-sec').length;
        报('');
        报('分了 ' + 段数 + ' 段。');
    }
    报('');
    报('以上只核对渲染与排版。变量写回、游戏结算与正文联动仍然要在酒馆实机里验。');
}
