import { onUnmounted, ref } from 'vue';

const 星期 = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'];

function 排版(日期: Date) {
  const 时 = String(日期.getHours()).padStart(2, '0');
  const 分 = String(日期.getMinutes()).padStart(2, '0');
  return {
    日期: `${日期.getFullYear()}年${日期.getMonth() + 1}月${日期.getDate()}日 ${星期[日期.getDay()]}`,
    时间: `${时}:${分}`,
  };
}

/** 现实时钟。面板顶部那一行用它，每 15 秒走一次，不用秒级跳动。 */
export function use现实时钟() {
  const 现在 = ref(排版(new Date()));
  const 定时器 = window.setInterval(() => {
    现在.value = 排版(new Date());
  }, 15000);
  onUnmounted(() => window.clearInterval(定时器));
  return 现在;
}
