import type { 题 } from './题型';
import type { 小游戏种类 } from '../../面板数据';

/* 四款小游戏的题面生成与规则文案。
 *
 * 所有随机都发生在这里，游戏组件只负责画出来和接收点击。
 * 换题面不用碰界面，两边也不会各写一套规则。 */

const 出餐菜单: { 名: string; 类: '热菜' | '凉菜' }[] = [
  { 名: '红烧肉', 类: '热菜' },
  { 名: '番茄炒蛋', 类: '热菜' },
  { 名: '酸辣汤', 类: '热菜' },
  { 名: '小炒肉', 类: '热菜' },
  { 名: '干煸豆角', 类: '热菜' },
  { 名: '青椒肉丝', 类: '热菜' },
  { 名: '拍黄瓜', 类: '凉菜' },
  { 名: '拌木耳', 类: '凉菜' },
  { 名: '口水鸡', 类: '凉菜' },
  { 名: '皮蛋豆腐', 类: '凉菜' },
  { 名: '凉拌三丝', 类: '凉菜' },
  { 名: '蘸水白肉', 类: '凉菜' },
];

const 分拣单: { 名: string; 区: '东区' | '西区' | '南区' | '北区' }[] = [
  { 名: '王记杂货', 区: '东区' },
  { 名: '老陈五金', 区: '东区' },
  { 名: '刘姐早点', 区: '西区' },
  { 名: '五金建材', 区: '西区' },
  { 名: '南门理发', 区: '南区' },
  { 名: '菜场东头', 区: '南区' },
  { 名: '北巷文具', 区: '北区' },
  { 名: '针织二厂', 区: '北区' },
  { 名: '河沿粮油', 区: '西区' },
  { 名: '铁西修车', 区: '东区' },
];

const 路况: { 说: string; 取: '近' | '远' }[] = [
  { 说: '下班高峰，主路堵得动不了', 取: '近' },
  { 说: '巷子里在修路，只留一条道', 取: '近' },
  { 说: '这个点主路空着，巷子全是人和摊子', 取: '远' },
  { 说: '前面路口查车，排了两百米', 取: '远' },
  { 说: '下过雨，小路全是水坑', 取: '近' },
  { 说: '老小区那段没路灯，夜里不好走', 取: '远' },
  { 说: '学校刚放学，门口那条街挤满人', 取: '远' },
];

function 抽<T>(表: T[]): T {
  return 表[Math.floor(Math.random() * 表.length)];
}

function 造出餐(): 题 {
  const 菜 = 抽(出餐菜单);
  const 正解 = 菜.类 === '热菜' ? 0 : 1;
  return {
    问: `窗口单子出来了：${菜.名}`,
    类: '该先出还是押后',
    正解,
    选项: [{ 名: '先出' }, { 名: '押后' }],
    错说: `${菜.名}是${菜.类}，得${正解 === 0 ? '先出' : '押后'}。`,
  };
}

function 造搬料(): 题 {
  const 已装 = 10 + Math.floor(Math.random() * 8) * 10;
  const 正解值 = 100 - 已装;
  // 错的那个选项不能碰巧等于正解，否则这题有两个正确答案
  let 错值 = 正解值 + (Math.random() < 0.5 ? -10 : 10);
  if (错值 === 正解值 || 错值 <= 0) 错值 = 正解值 + 20;
  const 正解在下标几 = Math.random() < 0.5 ? 0 : 1;
  const 选项 =
    正解在下标几 === 0 ? [{ 名: `加 ${正解值}` }, { 名: `加 ${错值}` }] : [{ 名: `加 ${错值}` }, { 名: `加 ${正解值}` }];
  return {
    问: `车上已经装了 ${已装}，还差多少够 100`,
    正解: 正解在下标几,
    选项,
    错说: `这一趟只能装到 100，差 ${正解值}。`,
  };
}

function 造分拣(): 题 {
  const 单 = 抽(分拣单);
  const 区表: ('东区' | '西区' | '南区' | '北区')[] = ['东区', '西区', '南区', '北区'];
  const 正解 = 区表.indexOf(单.区);
  return {
    问: `面单上写着：${单.名}`,
    类: '丢哪个筐',
    正解,
    选项: 区表.map(名 => ({ 名 })),
    错说: `${单.名}是${单.区}的件。`,
  };
}

function 造送货(): 题 {
  const 情况 = 抽(路况);
  const 正解 = 情况.取 === '近' ? 0 : 1;
  return {
    问: `站在路口，${情况.说}`,
    类: '走近路还是走大路',
    正解,
    选项: [{ 名: '穿巷子走近路' }, { 名: '绕主路走大路' }],
    错说: '这一趟绕远了，下一单就赶不上点了。',
  };
}

export type 小游戏规格 = {
  规则: string;
  造题: (序号: number, 总题数: number) => 题;
};

export function 取小游戏规则(): Record<小游戏种类, 小游戏规格> {
  return {
    出餐顺序: {
      规则: '热菜先出，凉菜押后。看清单子上的菜名再点。',
      造题: () => 造出餐(),
    },
    搬料配重: {
      规则: '这一趟只能装到 100，算一下还差多少。',
      造题: () => 造搬料(),
    },
    分拣: {
      规则: '照面单上的店名，把包裹丢进对应的片区筐。',
      造题: () => 造分拣(),
    },
    送货路线: {
      规则: '三个地址，每个路口选一条路。',
      造题: () => 造送货(),
    },
  };
}
